-- Daily challenges for 2026-10-28: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-28. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('trusting-yourself-more', 'Trusting Yourself More', 'For anyone who second-guesses every choice or checks with everyone else before deciding. Each day is one small way to notice your own good sense, keep promises to yourself and let your judgment count.', 'Confidence', 365, array['Self-Esteem', 'Decision Making', 'Values']::text[], 1, '2026-10-28T17:00:00+00:00'::timestamptz),
  ('making-days-off-feel-restful', 'Making Days Off Feel Restful', 'For anyone whose weekends or days off vanish into errands, catch-up work and screens. Each day is one small way to slow down, leave work behind and make your time off feel like time that is yours.', 'Rest', 365, array['Self-Care', 'Burnout', 'Habits']::text[], 1, '2026-10-28T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('trusting-yourself-more', 'making-days-off-feel-restful');

